// Payload: { request_id, decision: 'approved'|'rejected', approver_name, employee_name, employee_user_id, start_date, end_date, days, note }
const b = $input.first().json.body;
const ok = b.decision === 'approved';
const items = [];
if (b.employee_user_id) items.push({ json: { user_id: b.employee_user_id,
  title: ok ? 'Đơn nghỉ phép đã được duyệt' : 'Đơn nghỉ phép bị từ chối',
  message: `${b.approver_name} ${ok ? 'đã duyệt' : 'đã từ chối'} đơn nghỉ ${b.days} ngày (${b.start_date} → ${b.end_date}).` + (b.note ? ` Ghi chú: ${b.note}` : ''),
  ref_type: 'leave_request', ref_id: b.request_id, kind: ok ? 'leave.approved' : 'leave.rejected' } });
if (ok) items.push({ json: { role: 'hr', title: 'Cập nhật chấm công nghỉ phép',
  message: `${b.employee_name} nghỉ ${b.days} ngày (${b.start_date} → ${b.end_date}) đã được duyệt.`,
  ref_type: 'leave_request', ref_id: b.request_id, kind: 'leave.hr_fyi' } });
return items;
